-- ES/DE/FR translations for all 8 Poland milestones.

INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('pl-b2g-peppol', 'es', 'Facturación electrónica B2G obligatoria a través de Peppol', 'La facturación del sector público funciona sobre Peppol, completamente separada de la plataforma KSeF que más tarde gestionaría el B2B — los dos sistemas no comparten infraestructura.', '[]');
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('pl-b2g-peppol', 'de', 'B2G-E-Rechnungsstellung über Peppol verpflichtend', 'Die Rechnungsstellung des öffentlichen Sektors läuft über Peppol, vollständig getrennt von der später eingeführten KSeF-Plattform für B2B — die beiden Systeme teilen sich keine Infrastruktur.', '[]');
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('pl-b2g-peppol', 'fr', 'Facturation électronique B2G obligatoire via Peppol', 'La facturation du secteur public fonctionne sur Peppol, entièrement séparée de la plateforme KSeF qui gérerait plus tard le B2B — les deux systèmes ne partagent aucune infrastructure.', '[]');
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('pl-ksef2-api-published', 'es', 'Se publica la documentación final de la API de KSeF 2.0 y el esquema FA(3)', 'El Ministerio de Finanzas publicó la especificación OpenAPI 3.0.4, guías de integración con ejemplos en C#/Java, SDKs de .NET y Java, y la estructura lógica final FA(3) — sustituyendo a FA(2) y configurada mediante consulta pública con empresas, contables y proveedores de TI.', '[]');
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('pl-ksef2-api-published', 'de', 'Finale KSeF-2.0-API-Dokumentation und FA(3)-Schema veröffentlicht', 'Das Finanzministerium veröffentlichte die OpenAPI-3.0.4-Spezifikation, Integrationsleitfäden mit C#/Java-Beispielen, .NET- und Java-SDKs sowie die finale logische Struktur FA(3) — als Ersatz für FA(2) und geformt durch öffentliche Konsultation mit Unternehmen, Steuerberatern und IT-Anbietern.', '[]');
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('pl-ksef2-api-published', 'fr', 'La documentation finale de l''API KSeF 2.0 et le schéma FA(3) sont publiés', 'Le ministère des Finances a publié la spécification OpenAPI 3.0.4, des guides d''intégration avec exemples C#/Java, des SDK .NET et Java, et la structure logique finale FA(3) — remplaçant FA(2) et façonnée par une consultation publique avec les entreprises, comptables et fournisseurs informatiques.', '[]');
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('pl-test-environment', 'es', 'Se abre el entorno de pruebas de KSeF 2.0', 'Los integradores y las empresas obtienen acceso a un entorno de pruebas para la planificación arquitectónica y el desarrollo de prototipos antes de la implementación obligatoria.', '[]');
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('pl-test-environment', 'de', 'KSeF-2.0-Testumgebung wird eröffnet', 'Integratoren und Unternehmen erhalten Zugang zu einer Sandbox für die Architekturplanung und Prototypenentwicklung vor der verpflichtenden Einführung.', '[]');
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('pl-test-environment', 'fr', 'L''environnement de test KSeF 2.0 ouvre', 'Les intégrateurs et les entreprises obtiennent l''accès à un bac à sable pour la planification architecturale et le développement de prototypes avant le déploiement obligatoire.', '[]');
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('pl-certificates-available', 'es', 'Los certificados KSeF están disponibles', 'Los contribuyentes pueden empezar a solicitar certificados KSeF a través del Módulo de Certificados y Autorizaciones (MCU) — la credencial que sustituirá por completo a la autenticación basada en token a partir de enero de 2027.', '[]');
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('pl-certificates-available', 'de', 'KSeF-Zertifikate werden verfügbar', 'Steuerzahler können ab jetzt KSeF-Zertifikate über das Modul für Zertifikate und Berechtigungen (MCU) beantragen — die Berechtigung, die die tokenbasierte Authentifizierung ab Januar 2027 vollständig ersetzen wird.', '[]');
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('pl-certificates-available', 'fr', 'Les certificats KSeF deviennent disponibles', 'Les contribuables peuvent commencer à demander des certificats KSeF via le module des certificats et autorisations (MCU) — l''identifiant qui remplacera entièrement l''authentification par jeton à partir de janvier 2027.', '[]');
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('pl-large', 'es', 'KSeF obligatorio — grandes contribuyentes (>200 millones PLN)', 'Los grandes contribuyentes con una facturación superior a 200 millones de PLN se convirtieron en el primer grupo obligado a emitir facturas B2B a través de la plataforma de compensación Krajowy System e-Faktur (KSeF).', '["Intégrese con KSeF a través de la API usando el esquema XML FA(3)", "Configure las autorizaciones KSeF para el personal y cualquier emisor externo"]');
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('pl-large', 'de', 'KSeF verpflichtend — Großsteuerzahler (>200 Mio. PLN)', 'Großsteuerzahler mit einem Umsatz über 200 Millionen PLN wurden die erste Gruppe, die B2B-Rechnungen über die Clearing-Plattform Krajowy System e-Faktur (KSeF) ausstellen musste.', '["Integrieren Sie sich über die API mit KSeF unter Verwendung des FA(3)-XML-Schemas", "Richten Sie KSeF-Berechtigungen für Mitarbeiter und etwaige externe Aussteller ein"]');
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('pl-large', 'fr', 'KSeF obligatoire — grands contribuables (>200 millions PLN)', 'Les grands contribuables dont le chiffre d''affaires dépasse 200 millions de PLN sont devenus le premier groupe tenu d''émettre des factures B2B via la plateforme de contrôle Krajowy System e-Faktur (KSeF).', '["Intégrez-vous à KSeF via l''API en utilisant le schéma XML FA(3)", "Mettez en place les autorisations KSeF pour le personnel et tout émetteur tiers"]');
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('pl-all', 'es', 'KSeF obligatorio — todas las demás empresas registradas a efectos de IVA', 'El mandato KSeF se extendió a todas las empresas restantes registradas a efectos de IVA en Polonia (excluyendo a los microempresarios); una factura solo tiene validez legal una vez que KSeF la ha compensado.', '["Confirme que su sistema de facturación genera facturas estructuradas FA(3) válidas", "Las notas de corrección (noty korygujące) ya no son válidas — use el proceso de corrección estructurado de KSeF en su lugar", "Añada el número de factura KSeF a las referencias de transferencia bancaria una vez que ese requisito entre en vigor (1 de agosto de 2026)"]');
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('pl-all', 'de', 'KSeF verpflichtend — alle übrigen umsatzsteuerpflichtigen Unternehmen', 'Die KSeF-Vorgabe wurde auf alle verbleibenden umsatzsteuerpflichtigen Unternehmen in Polen ausgeweitet (mit Ausnahme von Kleinstunternehmern); eine Rechnung erlangt erst Rechtskraft, nachdem KSeF sie freigegeben hat.', '["Bestätigen Sie, dass Ihr Rechnungssystem gültige strukturierte FA(3)-Rechnungen erzeugt", "Korrekturnotizen (noty korygujące) sind nicht mehr gültig — nutzen Sie stattdessen den strukturierten Korrekturprozess von KSeF", "Fügen Sie die KSeF-Rechnungsnummer den Überweisungsreferenzen hinzu, sobald diese Anforderung in Kraft tritt (1. August 2026)"]');
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('pl-all', 'fr', 'KSeF obligatoire — toutes les autres entreprises assujetties à la TVA', 'L''obligation KSeF s''est étendue à toutes les entreprises restantes assujetties à la TVA en Pologne (à l''exclusion des micro-entrepreneurs) ; une facture n''a force légale qu''une fois validée par KSeF.', '["Confirmez que votre système de facturation génère des factures structurées FA(3) valides", "Les notes de correction (noty korygujące) ne sont plus valables — utilisez plutôt le processus de correction structuré de KSeF", "Ajoutez le numéro de facture KSeF aux références de virement bancaire une fois cette exigence en vigueur (1er août 2026)"]');
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('pl-grace-period-ends', 'es', 'Terminan el periodo de gracia de 2026 y la excepción para facturas pequeñas', 'El periodo de gracia de todo el año 2026 (sin sanciones financieras por errores de KSeF, independientemente de la fecha de inicio obligatoria de una empresa) expira, junto con la excepción que permite a los vendedores más pequeños (facturación bruta mensual ≤10.000 PLN) emitir fuera de KSeF.', '["Confirme que se han resuelto las brechas de integración con KSeF restantes antes de que comiencen las sanciones financieras", "Si ha estado confiando en la excepción para facturas pequeñas, confirme su preparación para KSeF antes de que expire"]');
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('pl-grace-period-ends', 'de', 'Die Übergangsfrist 2026 und die Kleinrechnungsausnahme enden beide', 'Die ganzjährige Übergangsfrist 2026 (keine finanziellen Sanktionen für KSeF-Fehler, unabhängig vom verpflichtenden Startdatum eines Unternehmens) läuft aus, ebenso wie die Ausnahme, die den kleinsten Verkäufern (≤10.000 PLN monatlicher Bruttorechnungsbetrag) die Ausstellung außerhalb von KSeF erlaubte.', '["Bestätigen Sie, dass verbleibende KSeF-Integrationslücken geschlossen sind, bevor finanzielle Sanktionen beginnen", "Wenn Sie sich auf die Kleinrechnungsausnahme verlassen haben, bestätigen Sie Ihre KSeF-Bereitschaft, bevor diese ausläuft"]');
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('pl-grace-period-ends', 'fr', 'La période de grâce 2026 et l''exception pour petites factures prennent fin', 'La période de grâce couvrant toute l''année 2026 (aucune sanction financière pour les erreurs KSeF, quelle que soit la date de démarrage obligatoire d''une entreprise) expire, de même que l''exception permettant aux plus petits vendeurs (facturation brute mensuelle ≤10 000 PLN) d''émettre en dehors de KSeF.', '["Confirmez que les lacunes d''intégration KSeF restantes sont résolues avant le début des sanctions financières", "Si vous vous appuyiez sur l''exception pour petites factures, confirmez votre préparation à KSeF avant son expiration"]');
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('pl-micro', 'es', 'KSeF obligatorio — microempresarios; comienzan las sanciones', 'Los microempresarios se incorporan al mandato KSeF, y el periodo de gracia sobre las sanciones financieras (hasta el 100% del IVA de la factura por incumplimiento) termina para todos.', '["Microempresas: confirmen que la integración con KSeF está activa mucho antes de esta fecha", "Todas las empresas: resuelvan cualquier brecha de cumplimiento pendiente antes de que se apliquen las sanciones"]');
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('pl-micro', 'de', 'KSeF verpflichtend — Kleinstunternehmer; Sanktionen beginnen', 'Kleinstunternehmer treten der KSeF-Vorgabe bei, und die Übergangsfrist für finanzielle Sanktionen (bis zu 100 % der Rechnungs-USt bei Nichteinhaltung) endet für alle.', '["Kleinstunternehmen: Bestätigen Sie, dass die KSeF-Integration weit vor diesem Datum aktiv ist", "Alle Unternehmen: Beheben Sie verbleibende Compliance-Lücken, bevor Sanktionen gelten"]');
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('pl-micro', 'fr', 'KSeF obligatoire — micro-entrepreneurs ; les sanctions commencent', 'Les micro-entrepreneurs rejoignent l''obligation KSeF, et la période de grâce sur les sanctions financières (jusqu''à 100 % de la TVA de la facture en cas de non-conformité) prend fin pour tous.', '["Micro-entreprises : confirmez que l''intégration KSeF est active bien avant cette date", "Toutes les entreprises : résolvez tout écart de conformité persistant avant l''application des sanctions"]');
